class Button {
  private _root?: HTMLElement;
  get root(): HTMLElement {
    if (!this._root) {
      this._root = document.createElement('button');
      this._root.textContent = 'Save';
    }
    return this._root;
  }
  render() { return this.root; }
}

class ReportService {
  private _report?: HeavyReport;
  get report(): HeavyReport {
    if (!this._report) {
      this._report = new HeavyReport();
    }
    return this._report;
  }
  generate() { return this.report.compute(); }
}

// Version A: explicit construction in constructor
class ProfileCard {
  private avatar: HTMLElement;
  constructor() {
    this.avatar = document.createElement('img');
    this.avatar.className = 'avatar';
  }
  render() { return this.avatar; }
}

// Version B: deferred creation in a getter
class ProfileCardLazy {
  private _avatar?: HTMLElement;
  get avatar(): HTMLElement {
    if (!this._avatar) {
      this._avatar = document.createElement('img');
      this._avatar.className = 'avatar';
    }
    return this._avatar;
  }
  render() { return this.avatar; }
}
